import{_ as a,o as r,c as t,ag as o}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"🔬 科学快报 | 2026年8月18日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-08-18.md","filePath":"science-log/src/reconstructed/2026-08-18.md"}'),n={name:"science-log/src/reconstructed/2026-08-18.md"};function i(s,e,l,u,h,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="🔬-科学快报-2026年8月18日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年8月18日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年8月18日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年8月18日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-05</p></blockquote><blockquote><p>说明：该日 Nature 主刊与 Science 正刊的 CrossRef 条目均为新闻/社论（<code>10.1038/d41586-*</code>、<code>10.1126/science.z*</code>），无可用的研究论文，故科学前沿 5 篇全部取自当日上线的 PNAS（Volume 123），AI 前沿 5 篇取自 arXiv cs.AI 当日提交。</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-herg-钾通道的-er-滞留基序决定-1a-1b-异源组装比例" tabindex="-1">🧬 hERG 钾通道的 ER 滞留基序决定 1a/1b 异源组装比例 <a class="header-anchor" href="#🧬-herg-钾通道的-er-滞留基序决定-1a-1b-异源组装比例" aria-label="Permalink to &quot;🧬 hERG 钾通道的 ER 滞留基序决定 1a/1b 异源组装比例&quot;">​</a></h3><p><strong>An ER retention motif controls the heteromeric stoichiometry of hERG1a/1b channels</strong><em>PNAS (2026)</em></p><p>hERG 钾通道是心肌动作电位复极化的核心，其 1a 与 1b 两种亚型的组装比例直接决定通道电流大小，但比例如何被细胞&quot;算&quot;出来一直不清楚。威斯康星大学麦迪逊分校 Gail A. Robertson 团队（第一作者 Sudharsan Kannan）在内质网滞留基序上找到了答案：1b 亚型带有一段滞留信号，单独存在时被扣在 ER 里出不去，只有与 1a 结合成异源四聚体才能&quot;解锁&quot;并运输到细胞膜。这条规则把组装化学计量比变成了一个可计算的运输竞争问题——1a 的产量决定了能带走多少 1b。该机制为长 QT 综合征等 hERG 相关心律失常提供了新的干预点：不是改通道电导，而是调亚基配比。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2605305123" target="_blank" rel="noreferrer">10.1073/pnas.2605305123</a></p><h3 id="🛡️-病毒入侵后核-dna-外泄才是-cgas-被激活的真正开关" tabindex="-1">🛡️ 病毒入侵后核 DNA 外泄才是 cGAS 被激活的真正开关 <a class="header-anchor" href="#🛡️-病毒入侵后核-dna-外泄才是-cgas-被激活的真正开关" aria-label="Permalink to &quot;🛡️ 病毒入侵后核 DNA 外泄才是 cGAS 被激活的真正开关&quot;">​</a></h3><p><strong>Expulsion of nuclear DNA to the cytoplasm after viral entry: A mechanism for activation of the cGAS pathway</strong><em>PNAS (2026)</em></p><p>cGAS-STING 是细胞内识别&quot;异位 DNA&quot;的先天免疫警报器，但长期以来一个悖论未解：病毒感染时，究竟是病毒 DNA 本身还是宿主自身 DNA 触发了 cGAS？哈佛医学院 Blavatnik 研究所（Nicolás Romero、Max E. Mertens、Maria Ericsson 等）用电子显微镜追踪了病毒进入后的超微结构变化，发现病毒入侵会诱导<strong>核膜完整性受损、核 DNA 被挤到细胞质</strong>，这些自体 DNA 才是 cGAS 的主要配体。这解释了为什么许多不含 DNA 的病毒（甚至某些 RNA 病毒）同样能激活 cGAS 通路，也把&quot;核-质 DNA 区隔&quot;确立为免疫监视的关键变量。对自身免疫病与抗病毒佐剂设计都有直接含义。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2614472123" target="_blank" rel="noreferrer">10.1073/pnas.2614472123</a></p><h3 id="🫁-鼻内传入神经的-放电频率-编码焦虑水平" tabindex="-1">🫁 鼻内传入神经的&quot;放电频率&quot;编码焦虑水平 <a class="header-anchor" href="#🫁-鼻内传入神经的-放电频率-编码焦虑水平" aria-label="Permalink to &quot;🫁 鼻内传入神经的&quot;放电频率&quot;编码焦虑水平&quot;">​</a></h3><p><strong>A nose-to-brain circuit underlies anxiety regulation by nasal afferent frequency in mice</strong><em>PNAS (2026)</em></p><p>呼吸与情绪的关系被观察到很多年（深呼吸能缓解焦虑），但通路一直含糊。复旦大学脑科学研究院、上海浦东医院团队（Xinsong Guo、Mengyan Liu、Qingcheng Xiong 等）在小鼠中锁定了一条&quot;鼻-脑&quot;直接回路：鼻腔嗅上皮的传入神经末梢感受气流机械刺激，其<strong>放电频率</strong>而非幅度被转译成焦虑相关核团的驱动强度。人为把鼻内传入频率调到特定区间，可以在不改变血氧、不改变呼吸总量的前提下双向调节焦虑样行为。这条通路绕过了经典的嗅球-皮层路径，把&quot;呼吸节律&quot;从背景生理变量提升为情绪状态的控制参数，也为经鼻干预（节律性呼吸训练、鼻内刺激）提供了可验证的神经底物。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2603853123" target="_blank" rel="noreferrer">10.1073/pnas.2603853123</a></p><h3 id="🧫-液晶环境中的细菌菌落形态发生" tabindex="-1">🧫 液晶环境中的细菌菌落形态发生 <a class="header-anchor" href="#🧫-液晶环境中的细菌菌落形态发生" aria-label="Permalink to &quot;🧫 液晶环境中的细菌菌落形态发生&quot;">​</a></h3><p><strong>Morphogenesis of bacterial colonies in liquid crystalline environments</strong><em>PNAS (2026)</em></p><p>细菌菌落常被当作各向同性的&quot;圆的扩散&quot;，但真实宿主表面（黏液、细胞膜）是液晶态的。普林斯顿 Lewis-Sigler 研究所 Ned S. Wingreen 团队联合数学家（Sebastian Gonzalez La Corte、Thomas G. J. Chandler、Saverio E. Spagnolie）把菌落生长放进向列相液晶中建模并实验验证：液晶的指向场给细菌提供了各向异性的有效扩散张量，菌落边界不再是圆，而会长出与指向矢对齐的分支/条纹图案；液晶的拓扑缺陷成为菌落成核与分裂的优先位点。结果把&quot;菌落形态&quot;从纯粹的生化参数问题变成了<strong>几何与场论问题</strong>——宿主微环境的取向序直接写进了菌落的形状。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2536343123" target="_blank" rel="noreferrer">10.1073/pnas.2536343123</a></p><h3 id="🐦-城市化削弱全球鸟类纬度多样性梯度" tabindex="-1">🐦 城市化削弱全球鸟类纬度多样性梯度 <a class="header-anchor" href="#🐦-城市化削弱全球鸟类纬度多样性梯度" aria-label="Permalink to &quot;🐦 城市化削弱全球鸟类纬度多样性梯度&quot;">​</a></h3><p><strong>Urbanization weakens the global latitudinal diversity gradient in birds</strong><em>PNAS (2026)</em></p><p>&quot;越靠近赤道物种越多&quot;是生态学最稳固的宏观格局之一，但它在人类改造的环境里是否还成立？麦吉尔大学（Jory Griffith、Jennifer M. Sunday、Anna L. Hargreaves）整合全球城市与邻近自然生境的鸟类群落数据，发现城市群落的物种丰富度纬度梯度显著变平：热带城市丢失的物种远多于温带城市，导致城市间的多样性差异被压缩。原因是热带特化种对生境结构更敏感、扩散能力更弱，在城市过滤器中优先被筛掉。这意味着城市化不只是&quot;局部减少物种&quot;，而是在系统性地<strong>抹平一条行星尺度的生物地理律</strong>，也提示热带城市是全球保护投入的优先区。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2527860123" target="_blank" rel="noreferrer">10.1073/pnas.2527860123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🔐-一个门不够-智能体前置控制的-修复耦合-失效" tabindex="-1">🔐 一个门不够：智能体前置控制的&quot;修复耦合&quot;失效 <a class="header-anchor" href="#🔐-一个门不够-智能体前置控制的-修复耦合-失效" aria-label="Permalink to &quot;🔐 一个门不够：智能体前置控制的&quot;修复耦合&quot;失效&quot;">​</a></h3><p><strong>One Gate Is Not Enough: Composing Stateful Pre-Action Controls for Agentic AI</strong><em>arXiv (2026)</em></p><p>智能体执行有后果的动作前，通常要过好几道闸门：权限门、资源门、证据门。Gaston Besanson 指出一个被忽视的失效模式——<strong>修复耦合（remediation-induced control coupling）</strong>：A 门做的补救（替换证据、缩小参数）会改变 B 门正在评估的对象，使 B 门之前的判断失效，于是&quot;每关都通过&quot;却整体不安全。论文形式化了这种耦合，并给出 remediate-and-regate 协议：任何修复动作后必须把受影响的下游门重新评估一遍，在有界、幂等的前提下恢复逐动作可靠性。这是把形式化方法里&quot;状态变更需重验&quot;的直觉，第一次系统地搬到智能体运行时。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.18360" target="_blank" rel="noreferrer">2608.18360</a></p><h3 id="🧰-让-4b-小模型学会-任务条件下的最小权限" tabindex="-1">🧰 让 4B 小模型学会&quot;任务条件下的最小权限&quot; <a class="header-anchor" href="#🧰-让-4b-小模型学会-任务条件下的最小权限" aria-label="Permalink to &quot;🧰 让 4B 小模型学会&quot;任务条件下的最小权限&quot;&quot;">​</a></h3><p><strong>Task-Conditioned Least-Privilege Learning for Executable Terminal and MCP Agents</strong><em>arXiv (2026)</em></p><p>工具型智能体的典型事故不是&quot;不会做&quot;，而是&quot;用了不该有的权限做完&quot;。Alexander Tu 与 Michael Tu 认为仅靠外部权限门控不够，提出用后训练把最小权限内化成模型能力：每个动作执行前、以及执行后从实际效果出发，各审计一次，沿六个风险维度由确定性验证器打分。在终端与 MCP（Model Context Protocol）环境中，4B 参数模型被训练成按任务需要选择权限范围，显著降低了超额权限错误。价值在于把安全从&quot;外部围栏&quot;变成&quot;模型的先验倾向&quot;，让小模型在真实执行环境里也能守住授权边界。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.18351" target="_blank" rel="noreferrer">2608.18351</a></p><h3 id="📜-用治理记录做监督-验证器筛选的自训练" tabindex="-1">📜 用治理记录做监督：验证器筛选的自训练 <a class="header-anchor" href="#📜-用治理记录做监督-验证器筛选的自训练" aria-label="Permalink to &quot;📜 用治理记录做监督：验证器筛选的自训练&quot;">​</a></h3><p><strong>Governance Records as Supervision: Verifier-Selected Self-Training for Structured Workflow Repair</strong><em>arXiv (2026)</em></p><p>可机器验证的工作流会留下天然的&quot;治理记录&quot;：任务契约 → 模型尝试 → 验证器判决 → 被接受的输出。Jesus Salas 问的是：这些&quot;偶尔成功&quot;的记录能不能当监督信号，把昂贵的一次性能力固化成稳定能力？在结构不相交的全新 PlanBench 重规划用例上，Qwen3-14B 的 thinking 模式只产出 24 个被独立编写的 VAL 验证器接受的计划；作者用这批&quot;验证器准入&quot;的输出训练同一 checkpoint 的非 thinking 执行路径，无需 oracle 目标、无需更强教师，VAL 接受率从 1/80 升到 57/80。八次 LoRA 的前瞻复制中目标、模型版本、配方、评测语料全部固定，说明增益来自筛选而非数据泄漏。这是&quot;验证器优于标注者&quot;在智能体工作流上的一个干净实证。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.18324" target="_blank" rel="noreferrer">2608.18324</a></p><h3 id="🧪-代码智能体的-锯齿前沿-语义等价改写就崩" tabindex="-1">🧪 代码智能体的&quot;锯齿前沿&quot;：语义等价改写就崩 <a class="header-anchor" href="#🧪-代码智能体的-锯齿前沿-语义等价改写就崩" aria-label="Permalink to &quot;🧪 代码智能体的&quot;锯齿前沿&quot;：语义等价改写就崩&quot;">​</a></h3><p><strong>A Jagged Frontier: Evaluating Robustness of Code Agents to Semantics-Preserving Transformations</strong><em>arXiv (2026)</em></p><p>代码智能体的跑分很高，但那是在&quot;原样代码&quot;上测的。Hasan Najib Mahmud 等提出随机变体采样器，对仓库级代码施加<strong>语义保持变换（SPTs）</strong>：控制流重写、死代码注入、标识符重命名，生成大量功能等价但表面不同的版本，再用两套智能体脚手架（mini-SWE agent、OpenCode）各配四个前沿模型（Claude Opus 4.5、Kimi K2.5、MiniMax M2.5、Qwen 3.6 系列）复测修 bug 能力。结论是能力边界呈&quot;锯齿状&quot;：同一模型在等价改写后成功率大幅波动，说明当前智能体很大程度上依赖表层模式而非语义理解。它给出的评测范式比单一分数更有信息量——鲁棒性应按变换类型分解。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.18389" target="_blank" rel="noreferrer">2608.18389</a></p><h3 id="⚛️-从一次廉价-dft-读出有效哈密顿量-逼近耦合簇精度" tabindex="-1">⚛️ 从一次廉价 DFT 读出有效哈密顿量，逼近耦合簇精度 <a class="header-anchor" href="#⚛️-从一次廉价-dft-读出有效哈密顿量-逼近耦合簇精度" aria-label="Permalink to &quot;⚛️ 从一次廉价 DFT 读出有效哈密顿量，逼近耦合簇精度&quot;">​</a></h3><p><strong>Coupled-cluster molecular properties across the main group that extrapolate beyond training size</strong><em>arXiv (2026)</em></p><p>耦合簇（CC）是分子电子结构的精度金标准，但随体系规模陡峭增长；DFT 便宜却系统性偏差。Wenhao He、Xu Chen、Noah Song 等提出 HARP（Hamiltonian Read-out for Properties）：用单个等变网络，从<strong>一次</strong>廉价的 B3LYP/def2-SVP 计算预测有效单电子哈密顿量，再由该哈密顿量一次性导出能量、光学带隙、偶极、四极、极化率、Mulliken 电荷、Mayer 键级等一整套性质，在九个主族元素（含磷、硫、氯等欠服务元素）上达到耦合簇精度。关键是&quot;读 Hamiltonian 而非直接读性质&quot;——单一中间表示让多任务共享物理结构，因此在外推到超出训练集规模时仍成立。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.18346" target="_blank" rel="noreferrer">2608.18346</a></p><blockquote><p>📅 日期：2026-08-18 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 📌 期号：不详（第 ? 期 · 事后重建版）</p></blockquote>',46)])])}const d=a(n,[["render",i]]);export{g as __pageData,d as default};
